        "AliasTarget": {
          "DNSName": { "Fn::GetAtt": ["PrimaryALB", "DNSName"] },
          "HostedZoneId": { "Fn::GetAtt": ["PrimaryALB", "CanonicalHostedZoneID"] }
        }
      }
    }
  }
